# 成交量確認參數（因子①）
VOL_MA_PERIOD = 20
VOL_SPIKE_TODAY = 1.5    # 形態出現日：成交量 > MA 的倍數
VOL_SPIKE_NEXT = 1.2     # 次日跟進：成交量 > MA 的倍數

