# ─── 行業分類 ────────────────────────────────────────────────────────────────

def fetch_sp500_sectors() -> pd.DataFrame:
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
    url = 'https://en.wikipedia.org/wiki/List_of_S%26P_500_companies'
    resp = requests.get(url, headers=headers, timeout=15)
    tables = pd.read_html(StringIO(resp.text))
    df = tables[0][['Symbol', 'GICS Sector', 'GICS Sub-Industry']].rename(
        columns={'Symbol': 'ticker', 'GICS Sector': 'sector',
                 'GICS Sub-Industry': 'subsector'})
    df['ticker'] = df['ticker'].str.strip()
    return df


def fetch_hsi_sectors() -> pd.DataFrame:
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
    url = 'https://en.wikipedia.org/wiki/Hang_Seng_Index'
    resp = requests.get(url, headers=headers, timeout=15)
    tables = pd.read_html(StringIO(resp.text))
    for t in tables:
        cols = [str(c) for c in t.columns.tolist()]
        if any('Ticker' in c or 'Sub-index' in c for c in cols):
            df = t.copy()
            df.columns = [str(c) for c in df.columns]
            ticker_col = [c for c in df.columns if 'Ticker' in c][0]
            sector_col = [c for c in df.columns if 'Sub-index' in c][0]
            def convert_hk(tk):
                tk = str(tk).replace('SEHK:\xa0', '').replace('SEHK:', '').strip()
                return tk.zfill(4) + '.HK'
            df['ticker'] = df[ticker_col].apply(convert_hk)
            df['sector'] = df[sector_col]
            df['subsector'] = df['sector']
            return df[['ticker', 'sector', 'subsector']]
    return pd.DataFrame(columns=['ticker', 'sector', 'subsector'])


# ─── 形態索引 ────────────────────────────────────────────────────────────────

@dataclass
class PatternIndex:
    pattern: Pattern
    def covers(self, idx: int) -> bool:
        return idx in self.pattern.indices


def build_pattern_index(df: pd.DataFrame) -> Tuple[dict, dict]:
    bullish_index: dict = defaultdict(list)
    bearish_index: dict = defaultdict(list)

    for idx in range(5, len(df)):
        for detector in [
            lambda i: detect_doji(df, i), lambda i: detect_hammer(df, i),
            lambda i: detect_shooting_star(df, i), lambda i: detect_morning_star(df, i),
            lambda i: detect_evening_star(df, i), lambda i: detect_engulfing(df, i),
            lambda i: detect_harami(df, i),
        ]:
            try:
                p = detector(idx)
                if p and p.confidence >= MIN_PATTERN_CONFIDENCE:
                    pi = PatternIndex(p)
                    for i in p.indices:
                        if p.direction == 'bullish' and p.name in CORE_BULLISH_PATTERNS:
                            bullish_index[i].append(pi)
                        elif p.direction == 'bearish':
                            bearish_index[i].append(pi)
            except Exception:
                pass

    for detector in [detect_support_resistance, detect_flag, detect_triangle]:
        try:
            patterns = detector(df)
            for p in patterns:
                if p.confidence < MIN_PATTERN_CONFIDENCE:
                    continue
                pi = PatternIndex(p)
                for i in p.indices:
                    if p.direction == 'bullish' and p.name in CORE_BULLISH_PATTERNS:
                        bullish_index[i].append(pi)
                    elif p.direction == 'bearish':
                        bearish_index[i].append(pi)
        except Exception:
            pass

    return bullish_index, bearish_index


# ─── 數據加載 ───────────────────────────────────────────────────────────────

def load_latest_prices(symbols: List[str], days: int = 90) -> Dict[str, pd.DataFrame]:
    """從 DuckDB 載入最近 N 天的股價數據"""
    if not symbols:
        return {}

    db_path = Path(__file__).parent / 'data' / 'prices.ddb'
    conn = duckdb.connect(str(db_path), read_only=True)

    placeholders = ','.join(['?' for _ in symbols])
    df = pd.read_sql(f"""
        SELECT symbol, trade_date, open, high, low, close, volume
        FROM stock_prices
        WHERE symbol IN ({placeholders})
        ORDER BY symbol, trade_date DESC
    """, conn, params=symbols)
    conn.close()

    # 翻轉（由新到舊→由舊到新），每股票取最近 days 行
    result = {}
    for sym, grp in df.groupby('symbol'):
        grp = grp.sort_values('trade_date').tail(days).reset_index(drop=True)
        grp['trade_date'] = pd.to_datetime(grp['trade_date'])
        grp.set_index('trade_date', inplace=True)
        result[sym] = grp

    return result


def load_ticker_sector_map() -> Tuple[Dict[str, str], Dict[str, str]]:
    """返回 {ticker: sector, ...} 和 {ticker: subsector, ...}"""
    sp500 = fetch_sp500_sectors()
    hsi = fetch_hsi_sectors()
    combined = pd.concat([sp500, hsi], ignore_index=True)

    sector_map = dict(zip(combined['ticker'], combined['sector']))
    subsector_map = dict(zip(combined['ticker'], combined['subsector']))

    # Wikipedia 行業 fallback for Nasdaq 100（不在 SP500 中的股票）
    sp500_tickers = set(load_constituents('sp500'))
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
    try:
        url = 'https://en.wikipedia.org/wiki/Nasdaq-100'
        resp = requests.get(url, headers=headers, timeout=15)
        tables = pd.read_html(StringIO(resp.text))
        for t in tables:
            cols = [str(c) for c in t.columns.tolist()]
            if 'Ticker' in cols and any('ICB Industry' in c for c in cols):
                ticker_col = [c for c in cols if c == 'Ticker'][0]
                sector_col = [c for c in cols if 'ICB Industry' in c][0]
                subsector_col = [c for c in cols if 'ICB Subsector' in c][0]
                for _, row in t.iterrows():
                    tk = str(row[ticker_col]).strip()
                    if tk not in sector_map and tk not in sp500_tickers:
                        sector_map[tk] = row[sector_col] if pd.notna(row[sector_col]) else 'Unknown'
                        subsector_map[tk] = row[subsector_col] if pd.notna(row[subsector_col]) else 'Unknown'
                break
    except Exception:
        pass

    return sector_map, subsector_map


def load_constituents(market: str) -> List[str]:
    if market == 'sp500':
        path = Path(__file__).parent / 'data' / 'constituents_sp500.txt'
    elif market == 'nasdaq':
        path = Path(__file__).parent / 'data' / 'constituents_nasdaq100.txt'
    elif market == 'dow':
        path = Path(__file__).parent / 'data' / 'constituents_dow.txt'
    else:
        path = Path(__file__).parent / 'data' / 'constituents_hsi.txt'
    with open(path, 'r') as f:
        return [line.strip() for line in f if line.strip()]


# ─── 核心掃描邏輯 ────────────────────────────────────────────────────────────

@dataclass
class ScanSignal:
    symbol: str
    sector: str
    subsector: str
    indicator: str
    signal_name: str
    pattern: str
    pattern_confidence: float
    confidence: float       # 綜合信心度 (指標 × 形態)
    win_rate: float         # 歷史勝率（從最佳組合表查得，個股級優先）
    win_rate_stock: float   # 個股級勝率（該股票自己的歷史）
    win_rate_sector: float  # Sector 級勝率（同行業所有股票平均）
    stock_n: int           # 個股級樣本數（無數據時為 0）
    sector_n: int          # Sector 級樣本數（無數據時為 0）
    avg_return: float       # 歷史平均回報
    price: float
    tp1_price: float        # 第一止盈目標價（保守，avg_return × 1.0）
    tp2_price: float        # 第二止盈目標價（進取，avg_return × 2.0）
    sl_price: float         # 止損價（price × 0.99）
    date: str
    tier: int               # 1=最高, 2=中, 3=一般
    reasons: str            # 為何入選（文字說明）
    volume_confirmed: bool  # 因子①：成交量確認


# ─── 每檔股票最新日期信號跟蹤（scan_market 去重用）────────────────────────
_latest_sig: Dict[str, ScanSignal] = {}


def scan_ticker(
    sym: str, df: pd.DataFrame,
    sector: str, subsector: str,
    bullish_index: dict, bearish_index: dict
) -> List[ScanSignal]:
    """
    掃描單一股票，檢測最近 3 根 K 線內所有滿足條件的買入信號。
    包含因子①：成交量確認（形態日放量 1.5× + 次日跟進 1.2× MA20）
    """
    signals = []
    if df is None or len(df) < 30:
        return signals

    try:
        ind_df = calculate_all_indicators(df)
    except Exception:
        return signals

    # ── 計算成交量均線（因子①）─────────────────────────────
    ind_df = ind_df.copy()
    ind_df['vol_ma20'] = ind_df['volume'].rolling(VOL_MA_PERIOD, min_periods=10).mean()

    last_idx = len(ind_df) - 1

    # 檢查最近 3 根 K 線（信號可能出現在非最新日期）
    for lookback in range(0, 3):
        check_idx = last_idx - lookback
        if check_idx < 5:
            break

        bull_pis = bullish_index.get(check_idx, [])

        # ── 因子①：成交量確認 ──────────────────────────────
        vol_today_ok = vol_next_ok = False
        if check_idx + 1 < len(ind_df):
            vol_today = ind_df['volume'].iloc[check_idx]
            vol_ma = ind_df['vol_ma20'].iloc[check_idx]
            vol_next = ind_df['volume'].iloc[check_idx + 1]
            vol_ma_next = ind_df['vol_ma20'].iloc[check_idx + 1]
            if vol_ma > 0:
                vol_today_ok = vol_today >= vol_ma * VOL_SPIKE_TODAY
            if vol_ma_next > 0:
                vol_next_ok = vol_next >= vol_ma_next * VOL_SPIKE_NEXT
        vol_confirmed = vol_today_ok and vol_next_ok

        # ── 收集指標信號 ──
        all_ind_signals = []
        all_ind_signals.extend(detect_rsi_signals(ind_df, check_idx))
        all_ind_signals.extend(detect_macd_signals(ind_df, check_idx))
        all_ind_signals.extend(detect_kdj_signals(ind_df, check_idx))
        all_ind_signals.extend(detect_ema_signals(ind_df, check_idx))
        all_ind_signals.extend(detect_bb_signals(ind_df, check_idx))

        for ind_sig in all_ind_signals:
            ind_key = (ind_sig.indicator, ind_sig.name)
            if ind_key not in CORE_BULLISH_INDICATORS or ind_sig.signal_type != 'bullish':
                continue

            # ── 查找匹配的形態 ──
            matched_pattern = None
            matched_conf = 0.0
            for pi in bull_pis:
                if pi.pattern.confidence > matched_conf:
                    matched_pattern = pi.pattern.name
                    matched_conf = pi.pattern.confidence

            # ── 計算信心度（成交量確認額外加分）───────────────
            if matched_pattern:
                conf = min(1.0, ind_sig.confidence * 1.2 + matched_conf * 0.3)
                if vol_confirmed:
                    conf = min(1.0, conf * 1.15)  # 成交量確認額外 +15%
            else:
                conf = ind_sig.confidence * 0.7  # 無形態降權

            # ── 查歷史勝率（雙層查找：個股 → Sector → Fallback）────────
            has_pat = matched_pattern is not None
            vol_flag = 'Y' if vol_confirmed else 'N'
            pat_flag = 'Y' if has_pat else 'N'
            pat = matched_pattern or 'None'

            # 個股級 key（symbol, sector, signal, pattern, vol, has_pat）
            stock_key = (sym, sector, ind_sig.name, pat, vol_flag, pat_flag)
            global BEST_COMBOS_STOCK
            stock_hist = BEST_COMBOS_STOCK.get(stock_key)

            # Sector 級 key（sector, signal, pattern, vol, has_pat）
            # 優先完全匹配；若 vol='Y' 無記錄，則降級試 vol='N'
            sector_key = (sector, ind_sig.name, pat, vol_flag, pat_flag)
            sector_hist = BEST_COMBOS_SECTOR.get(sector_key)
            if not sector_hist and vol_flag == 'Y':
                sector_key = (sector, ind_sig.name, pat, 'N', pat_flag)
                sector_hist = BEST_COMBOS_SECTOR.get(sector_key)

            # Fallback key（signal, pattern, vol, pat_flag）— 4元素，與 BEST_COMBOS_FALLBACK 結構一致
            # 若 vol='Y' 無記錄，則降級試 vol='N'
            fb_key = (ind_sig.name, pat, vol_flag, pat_flag)
            fb_hist = BEST_COMBOS_FALLBACK.get(fb_key)
            if not fb_hist and vol_flag == 'Y':
                fb_key = (ind_sig.name, pat, 'N', pat_flag)
                fb_hist = BEST_COMBOS_FALLBACK.get(fb_key)

            # 選擇：優先個股，其次 Sector，最後 Fallback（n 分開追蹤）
            if stock_hist:
                win_rate_stock = stock_hist[0]
                stock_n = stock_hist[2]
                win_rate_sector = sector_hist[0] if sector_hist else None
                sector_n = sector_hist[2] if sector_hist else 0
                avg_return = stock_hist[1]
                win_rate = win_rate_stock
            elif sector_hist:
                win_rate_stock = None
                stock_n = 0
                win_rate_sector = sector_hist[0]
                sector_n = sector_hist[2]
                avg_return = sector_hist[1]
                win_rate = win_rate_sector
            else:
                win_rate_stock = None
                stock_n = 0
                win_rate_sector = None
                sector_n = 0
                # fb_hist 匹配不到時：勝率=50%（無參考價值），avg_return=2%，n=0
                avg_return = fb_hist[1] if fb_hist else 0.020
                win_rate = fb_hist[0] if fb_hist else 0.50

            # ── Tier 分級（n 門檻 + win_rate 門檻，兩者都要滿足）──────────
            # Tier 分級使用的 n：來自己實際採用的數據源（個股 > 板塊 > fallback）
            # 當所有數據源均無記錄時，tier_n = 0（無啞值，避免低樣本湊數進入 Tier 1/2）
            if stock_hist:
                tier_n = stock_n
            elif sector_hist:
                tier_n = sector_n
            else:
                tier_n = 0  # 無任何歷史數據時為 0，不湊數
            # Tier 1：有成交量確認的強信號
            if vol_confirmed and has_pat and matched_conf >= 0.7 and tier_n >= 8 and win_rate >= 0.50:
                tier = 1
            elif vol_confirmed and has_pat and tier_n >= 6 and win_rate >= 0.50:
                tier = 1
            # Tier 2：無成交量但歷史表現優秀
            elif has_pat and matched_conf >= 0.7 and tier_n >= 12 and win_rate >= 0.55:
                tier = 1
            elif has_pat and tier_n >= 10 and win_rate >= 0.55:
                tier = 2
            elif vol_confirmed and tier_n >= 6 and win_rate >= 0.45:
                tier = 2
            else:
                tier = 3

            # ── 構建 reasons ──
            reasons = []
            if sector in ['Information Technology', 'Financials', 'Energy',
                           'Utilities', 'Materials', 'Industrials', 'Consumer Staples']:
                reasons.append(f"✅ 強勢Sector（{sector}）")
            if vol_confirmed:
                reasons.append("📈 成交量確認（放量 + 跟進）")
            if matched_pattern:
                reasons.append(f"形態確認：{matched_pattern}（信心 {matched_conf:.0%}）")
            # ── 勝率顯示（啞值顯示為 —，n 分開追蹤）───────────────
            stock_str = f"{win_rate_stock:.0%}" if win_rate_stock is not None else "—"
            sector_str = f"{win_rate_sector:.0%}" if win_rate_sector is not None else "—"
            if stock_hist:
                reasons.append(f"勝率 {win_rate:.0%}（個股 {stock_str} (n={stock_n}) | 板塊 {sector_str} (n={sector_n})）")
            elif sector_hist:
                reasons.append(f"勝率 {win_rate:.0%}（個股 — | 板塊 {sector_str} (n={sector_n})）")
            else:
                reasons.append(f"參考勝率 {win_rate:.0%}（n=20）")

            sig_date = ind_df.index[check_idx]
            date_str = str(sig_date.date()) if hasattr(sig_date, 'date') else str(sig_date)[:10]

            entry_price = float(ind_df['close'].iloc[check_idx])
            # TP1（保守）：avg_return × 1.0；TP2（進取）：avg_return × 2.0；SL：-1%
            tp1_price = round(entry_price * (1 + avg_return), 2)
            tp2_price = round(entry_price * (1 + avg_return * 2), 2)
            sl_price = round(entry_price * 0.99, 2)

            signals.append(ScanSignal(
                symbol=sym,
                sector=sector,
                subsector=subsector,
                indicator=ind_sig.indicator,
                signal_name=ind_sig.name,
                pattern=matched_pattern or 'None',
                pattern_confidence=matched_conf,
                confidence=conf,
                win_rate=win_rate,
                win_rate_stock=win_rate_stock,
                win_rate_sector=win_rate_sector,
                stock_n=stock_n,
                sector_n=sector_n,
                avg_return=avg_return,
                price=entry_price,
                tp1_price=tp1_price,
                tp2_price=tp2_price,
                sl_price=sl_price,
                date=date_str,
                tier=tier,
                reasons=' | '.join(reasons),
                volume_confirmed=vol_confirmed,
            ))

    return signals


def scan_market(market: str, tier_filter: Optional[int] = None) -> List[ScanSignal]:
    """掃描整個市場"""
    if market == 'us-all':
        # 合併 SP500 + Nasdaq 100（去重，因為兩者有重疊）
        sp_tickers = load_constituents('sp500')
        nd_tickers = load_constituents('nasdaq')
        tickers = sorted(set(sp_tickers + nd_tickers))
        print(f"\n📡 掃描 美股全線 ({len(tickers)} 隻 = SP500 {len(sp_tickers)} + Nasdaq 獨有 {len(tickers)-len(sp_tickers)})...")
    else:
        tickers = load_constituents(market)
        print(f"\n📡 掃描 {market} ({len(tickers)} 隻股票)...")

    # 加載 Sector 映射（含 Yahoo Finance fallback for Nasdaq-only stocks）
    sector_map, subsector_map = load_ticker_sector_map()

    # 批量加載數據
    all_data = load_latest_prices(tickers, days=90)

    all_signals = []
    for i, sym in enumerate(tickers):
        df = all_data.get(sym)
        if df is None:
            continue

        sector = sector_map.get(sym, 'Unknown')
        subsector = subsector_map.get(sym, sector)

        bullish_index, _ = build_pattern_index(df)
        sigs = scan_ticker(sym, df, sector, subsector, bullish_index, {})

        # ── 每檔股票只保留最新日期的信號（不論 Tier）───────────────
        for sig in sigs:
            if sym not in _latest_sig or sig.date > _latest_sig[sym].date:
                _latest_sig[sym] = sig

        all_signals.extend(sigs)
        if (i + 1) % 100 == 0:
            print(f"  ... 已掃描 {i+1} 隻，發現 {len(all_signals)} 個信號")

    # ── 最終過濾：只保留每檔股票最新日期的信號 ───────────────────
    all_signals = [_latest_sig[sym] for sym in _latest_sig]
    _latest_sig.clear()   # 清理模組級狀態

    if tier_filter is not None:
        all_signals = [s for s in all_signals if s.tier <= tier_filter]

    print(f"  完成：共發現 {len(all_signals)} 個信號")
    return all_signals


def scan_tickers(tickers: List[str]) -> List[ScanSignal]:
    """掃描指定股票列表"""
    sector_map, subsector_map = load_ticker_sector_map()
    all_data = load_latest_prices(tickers, days=90)
    all_signals = []

    for sym in tickers:
        df = all_data.get(sym)
        if df is None:
            print(f"  ⚠️ 無 {sym} 數據")
            continue
        sector = sector_map.get(sym, 'Unknown')
        subsector = subsector_map.get(sym, sector)
        bullish_index, _ = build_pattern_index(df)
        sigs = scan_ticker(sym, df, sector, subsector, bullish_index, {})
        all_signals.extend(sigs)

    return all_signals


# ─── 輸出格式化 ─────────────────────────────────────────────────────────────

def format_signals(signals: List[ScanSignal], top_n: int = 20) -> str:
    """將信號列表格式化為 Telegram 友好文字"""
    if not signals:
        return "📡 今日無符合條件的信號"

    # 按 tier → win_rate → confidence 排序
    signals.sort(key=lambda s: (s.tier, -s.win_rate, -s.confidence))

    lines = []
    lines.append(f"📡 *今日信號掃描* — {datetime.now().strftime('%Y-%m-%d %H:%M')}")
    lines.append(f"共 {len(signals)} 個信號（顯示 Top {min(top_n, len(signals))}）\n")

    tier_labels = {1: '🔥 Tier-1', 2: '⚡ Tier-2', 3: '📊 Tier-3'}
    current_tier = None

    for i, sig in enumerate(signals[:top_n]):
        if sig.tier != current_tier:
            current_tier = sig.tier
            lines.append(f"\n{tier_labels.get(sig.tier, '')}")
            lines.append("─" * 40)

        price_str = f"${sig.price:.2f}" if sig.symbol.isupper() else f"HK${sig.price:.2f}"
        vol_icon = '📈' if sig.volume_confirmed else '⚪'
        flag = '🟢' if sig.win_rate >= 0.60 else ('🟡' if sig.win_rate >= 0.45 else '⚪')

        stock_str = f"{sig.win_rate_stock:.0%}" if sig.win_rate_stock is not None else "—"
        sector_str = f"{sig.win_rate_sector:.0%}" if sig.win_rate_sector is not None else "—"
        lines.append(
            f"{flag}{vol_icon} *{sig.symbol}* ({sig.sector[:15]})\n"
            f"   {sig.indicator}: {sig.signal_name}\n"
            f"   形態: {sig.pattern} | 勝率: {sig.win_rate:.0%}（個股 {stock_str} (n={sig.stock_n}) | 板塊 {sector_str} (n={sig.sector_n})）| 參考回報: {sig.avg_return:+.1%}\n"
            f"   {price_str} | {sig.reasons}"
        )

    return '\n'.join(lines)


def signals_to_dataframe(signals: List[ScanSignal]) -> pd.DataFrame:
    """將信號列表轉為 DataFrame（供 Dashboard 使用）"""
    if not signals:
        return pd.DataFrame()
    rows = []
    for s in signals:
        rows.append({
            'symbol': s.symbol,
            'sector': s.sector,
            'subsector': s.subsector,
            'indicator': s.indicator,
            'signal': s.signal_name,
            'pattern': s.pattern,
            'pattern_conf': s.pattern_confidence,
            'confidence': s.confidence,
            'win_rate': s.win_rate,
            'win_rate_stock': s.win_rate_stock,
            'win_rate_sector': s.win_rate_sector,
            'stock_n': s.stock_n,
            'sector_n': s.sector_n,
            'avg_return': s.avg_return,
            'price': s.price,
            'tp1_price': s.tp1_price,
            'tp2_price': s.tp2_price,
            'sl_price': s.sl_price,
            'date': s.date,
            'tier': s.tier,
            'volume_confirmed': s.volume_confirmed,
        })
    df = pd.DataFrame(rows)
    df = df.sort_values(['tier', 'win_rate', 'confidence'], ascending=[True, False, False])
    return df.reset_index(drop=True)


# ─── 執行入口 ───────────────────────────────────────────────────────────────

def main():
    parser = argparse.ArgumentParser(description='每日信號掃描引擎')
    parser.add_argument('--sp500', action='store_true', help='只掃描 S&P 500')
    parser.add_argument('--nasdaq', action='store_true', help='只掃描 Nasdaq 100')
    parser.add_argument('--dow', action='store_true', help='只掃描 Dow Jones 30')
    parser.add_argument('--us-all', action='store_true', help='掃描全部美股（SP500 + Nasdaq 100）')
    parser.add_argument('--hsi', action='store_true', help='只掃描 HSI')
    parser.add_argument('--ticker', type=str, help='掃描指定股票（如 0700.HK）')
    parser.add_argument('--tickers', type=str, help='逗號分隔股票列表')
    parser.add_argument('--tier', type=int, choices=[1, 2, 3], help='只輸出指定 Tier')
    parser.add_argument('--top', type=int, default=20, help='輸出前 N 個')
    parser.add_argument('--output', type=str, help='儲存為 CSV（指定路徑）')
    parser.add_argument('--save', action='store_true',
                        help='自動儲存到 data/signals/（用於 Dashboard 整合）')
    args = parser.parse_args()

    # 決定掃描範圍
    if args.ticker:
        signals = scan_tickers([args.ticker])
    elif args.tickers:
        signals = scan_tickers([t.strip() for t in args.tickers.split(',')])
    elif args.sp500:
        signals = scan_market('sp500', tier_filter=args.tier)
    elif args.nasdaq:
        signals = scan_market('nasdaq', tier_filter=args.tier)
    elif args.dow:
        signals = scan_market('dow', tier_filter=args.tier)
    elif args.us_all:
        signals = scan_market('us-all', tier_filter=args.tier)
    elif args.hsi:
        signals = scan_market('hsi', tier_filter=args.tier)
    else:
        # 默認：兩個市場都掃
        sigs_sp = scan_market('sp500', tier_filter=args.tier)
        sigs_hk = scan_market('hsi', tier_filter=args.tier)
        signals = sigs_sp + sigs_hk

    if not signals:
        print("📡 今日無符合條件的信號")
        # Even with no signals, save stub files for Dashboard
        if args.save:
            _save_signals_for_dashboard(signals, args)
        return

    # 輸出
    print(f"\n{'='*70}")
    print(format_signals(signals, top_n=args.top))
    print(f"{'='*70}")

    # 儲存 CSV
    if args.output:
        df = signals_to_dataframe(signals)
        out_path = Path(__file__).parent / args.output
        df.to_csv(out_path, index=False)
        print(f"\n💾 已儲存至 {out_path}")

    # ── --save: 自動儲存到 data/signals/（Dashboard 整合） ──────────────
    if args.save:
        _save_signals_for_dashboard(signals, args)


def _save_signals_for_dashboard(signals, args):
    """Save signal results to data/signals/ for Railway Dashboard consumption."""
    from pathlib import Path
    from datetime import date

    today = date.today().isoformat()
    base_dir = Path(__file__).parent / "data" / "signals"
    base_dir.mkdir(parents=True, exist_ok=True)

    df = signals_to_dataframe(signals)

    # ── Define the expected columns for empty stub files ──
    SIGNAL_COLUMNS = [
        'symbol', 'sector', 'subsector', 'indicator', 'signal', 'pattern',
        'pattern_conf', 'confidence', 'win_rate', 'win_rate_stock', 'win_rate_sector',
        'stock_n', 'sector_n', 'avg_return', 'price', 'tp1_price', 'tp2_price',
        'sl_price', 'date', 'tier', 'volume_confirmed'
    ]

    # Determine which markets were scanned from args
    scanned_us = any([args.sp500, args.nasdaq, args.dow, args.us_all]) or \
                 (not args.hsi and not args.ticker and not args.tickers)
    scanned_hk = args.hsi or (not args.sp500 and not args.nasdaq and not args.dow
                              and not args.us_all and not args.ticker and not args.tickers)

    # Separate US and HK signals by suffix
    df_us = df[~df['symbol'].str.endswith('.HK')].copy() if not df.empty else pd.DataFrame(columns=SIGNAL_COLUMNS)
    df_hk = df[df['symbol'].str.endswith('.HK')].copy() if not df.empty else pd.DataFrame(columns=SIGNAL_COLUMNS)

    def _save_market(df_part: pd.DataFrame, market_label: str, scanned: bool):
        """Save dated file + latest (overwrite) file.
        Only overwrites latest file if this market was actually scanned.
        If not scanned, only saves the dated file (for historical record).
        If file doesn't exist yet and not scanned, create a stub."""
        dated_path = base_dir / f"daily_signals_{market_label}_{today}.csv"
        latest_path = base_dir / f"latest_signals_{market_label}.csv"
        df_part.to_csv(dated_path, index=False)

        if scanned:
            df_part.to_csv(latest_path, index=False)  # Only overwrite latest when scanned
        elif not latest_path.exists() and df_part.empty:
            df_part.to_csv(latest_path, index=False)  # Create initial stub if missing

        count = len(df_part)
        if count > 0:
            print(f"  ✅ {market_label}: {count} 個信號 -> {dated_path.name}")

    # Also save combined
    if not df.empty:
        combined_dated = base_dir / f"daily_signals_all_{today}.csv"
        combined_latest = base_dir / "latest_signals_all.csv"
        df.to_csv(combined_dated, index=False)
        df.to_csv(combined_latest, index=False)
        print(f"  ✅ 合計: {len(df)} 個信號 -> {combined_dated.name}")

    _save_market(df_us, "us", scanned_us)
    _save_market(df_hk, "hk", scanned_hk)


